import type { JsonSerializable, Role } from '../app'
import type { FullSchema, Record, SystemColumns, TableName } from '../db'
import type { SPAngularProvider } from './SPAngularProvider'
import type { SPWidgetDependency } from './SPWidgetDependency'

type WidgetOptionSection = 'data' | 'behavior' | 'documentation' | 'presentation' | 'other'

// Widget plugin values -> record values
export const WidgetCategories = {
    standard: 'standard',
    otherApplications: 'other',
    custom: 'custom',
    sample: 'sample',
    knowledgeBase: 'kb',
    servicePortal: 'sp_platform',
    serviceCatalog: 'sc',
}

type WidgetOptionType =
    | 'string'
    | 'boolean'
    | 'integer'
    | 'reference'
    | 'choice'
    | 'fieldList'
    | 'fieldName'
    | 'glideList'
    | 'glyphIcon'

type WidgetOptionBase = {
    name: string
    label: string
    section: WidgetOptionSection
    type: WidgetOptionType
    defaultValue?: string
    hint?: string
}

type WidgetOptionChoice = { name: string; label: string }

type ChoiceWidgetOption = WidgetOptionBase & {
    type: 'choice'
    choices: WidgetOptionChoice[]
}

type GlideListWidgetOption = WidgetOptionBase & {
    type: 'glideList'
    table: string
}

type FieldListWidgetOption = WidgetOptionBase & {
    type: 'fieldList'
    table: string
}

export type SPTemplate = Now.Internal.WithID<{
    /** The id of the Angular template (required) */
    id: string
    /** The HTML template for the Angular template (required) */
    htmlTemplate: string
}>

export type WidgetOption = WidgetOptionBase | FieldListWidgetOption | ChoiceWidgetOption | GlideListWidgetOption

export type SPWidget<Table extends TableName = 'sp_instance'> = Now.Internal.WithID<
    {
        /** The name of the widget (required) */
        name: string
        /** The category of the widget (default is 'custom') */
        category?: keyof typeof WidgetCategories
        /** The client script for the widget */
        clientScript?: string
        /** The server script for the widget */
        serverScript?: string
        /** The controller for the widget (default is 'c') */
        controllerAs?: string
        /** The HTML template for the widget */
        htmlTemplate?: string
        /** The custom CSS for the widget */
        customCss?: string
        /** The data table for the widget (default is 'sp_instance') */
        dataTable?: Table
        /** The demo data for the widget */
        demoData?: JsonSerializable
        /** The description of the widget */
        description?: string
        /** The documentation for the widget */
        docs?: string | Record<'sp_documentation'>
        /** The fields for the widget */
        fields?: (keyof FullSchema<Table> | SystemColumns | (string & {}))[]
        /** Show the preview pane in the Service Portal editor */
        hasPreview?: boolean
        /** The unique id for the widget. Must contain alphanumeric, -, or _ characters */
        id?: string
        /** internal field used by ServiceNow developers */
        internal?: boolean
        /** The link script for the widget (client-side) */
        linkScript?: string
        /** The roles that can access the widget */
        roles?: (string | Role | Record<'sys_user_role'>)[]
        /** The option schema for the widget */
        optionSchema?: WidgetOption[]
        /** Whether the widget is public */
        public?: boolean
        /** Built by ServiceNow. On build, can only be true if scope has sn_ or snc_ prefix */
        servicenow?: boolean
        /** Array of widget dependencies */
        dependencies?: (string | Record<'sp_dependency'> | SPWidgetDependency)[]
        /** Array of Angular providers for the widget */
        angularProviders?: (string | Record<'sp_angular_provider'> | SPAngularProvider)[]
        /** Array of widget templates */
        templates?: SPTemplate[]
    } & Now.Internal.Meta
>

/**
 * API used to create a Service Portal widget (`sp_widget`). For
 * more information, see the {@link https://docs.servicenow.com/csh?version=latest&topicname=fluent-service-portal-api.html#fluent-sp-widget-object|ServiceNow docs}.
 */
export function SPWidget<T extends TableName>(config: SPWidget<T>) {
    return config
}
